import {chuteNames} from './recovery.js';
import {transferTargets,transferCapacity} from './fuel-transfer.js';
import {PARTS} from './catalog.js';
import {canControl} from './fleet.js';
import {floatingWindow} from './floating-window.js';
import {parachuteActions,setParachuteAction,partActions,setPartAction,setPartThrustLimit,setPartControlLimit} from './part-actions.js';
export function mountPartWindows(getFlight,beforeAction,highlight=()=>{}){
 const host=document.createElement('div');host.id='partWindows';document.body.append(host);const windows=new Map();let vessel=null;
 const close=id=>{highlight(null);windows.get(id)?.remove();windows.delete(id);};
 function clear(){highlight(null);for(const id of windows.keys())close(id);vessel=null;}
 function update(){const f=getFlight();if(f!==vessel){clear();return;}host.hidden=!f||!document.querySelector('#orbitOverlay').hidden;
  for(const [id,w]of windows){const p=f.parts.find(p=>p.id===id);if(!p){close(id);continue;}const d=PARTS[p.type];
   for(const a of partActions(f,id)){const row=w.content.querySelector('[data-action="'+a.key+'"]');row.checked=a.on;row.disabled=!canControl(f);row.parentElement.title=a.globalOff?'機体全体のスイッチがOFFです':'';row.parentElement.classList.toggle('globalOff',a.globalOff);row.parentElement.querySelector('small').textContent=a.globalOff?'機体全体OFF':'';}
   if(w.chute){const state=f.chutes.get(id);w.chute.status.textContent=(chuteNames[state?.status]||'不明')+' · '+Math.round((state?.fraction||0)*100)+'%';for(const a of parachuteActions(f,id))w.chute.buttons.get(a.key).disabled=!a.enabled;}
   if(w.limit){w.limit.value=String(Math.round((p.thrustLimit??1)*100));w.limit.disabled=!canControl(f);w.limitValue.textContent=w.limit.value+'%';}
   if(w.travel){w.travel.value=String((p.controlLimit??1)*Number(w.travel.max));w.travel.disabled=!canControl(f);w.travelValue.textContent=Number(w.travel.value).toFixed(1)+'°';}
   if(w.transfer){const choices=transferTargets(f,id),signature=choices.map(p=>p.id).join('|');if(w.transfer.signature!==signature){const previous=w.transfer.select.value;w.transfer.select.replaceChildren(...choices.map(p=>{const option=document.createElement('option');option.value=p.id;option.textContent=PARTS[p.type].name+' · '+(f.parts.indexOf(p)+1);return option;}));if(!choices.length){const option=document.createElement('option');option.value='';option.textContent='同系統のタンクなし';w.transfer.select.append(option);}if(choices.some(p=>p.id===previous))w.transfer.select.value=previous;else if(previous&&choices.length){const option=document.createElement('option');option.value='';option.textContent='移送相手を選択';option.disabled=true;w.transfer.select.prepend(option);w.transfer.select.value='';}w.transfer.signature=signature;}const other=choices.find(p=>p.id===w.transfer.select.value),amount=Number(w.transfer.amount.value),valid=Number.isFinite(amount)&&amount>0;w.transfer.send.disabled=!valid||!other||!(f.fuel.get(id)>0)||!(f.fuel.get(other.id)<transferCapacity(other));w.transfer.receive.disabled=!valid||!other||!(f.fuel.get(other.id)>0)||!(f.fuel.get(id)<transferCapacity(p));w.transfer.select.disabled=!choices.length;}
   const values=[];if(d.controlAxis)values.push('舵角 '+((f.deflections.get(id)||0)*180/Math.PI).toFixed(1)+'°');if(d.fuel||d.monoprop)values.push('推進剤 '+(f.fuel.get(id)||0).toFixed(1)+' / '+(d.fuel||d.monoprop)+' kg');if(d.battery)values.push('電力 '+(f.charge.get(id)||0).toFixed(1)+' / '+d.battery+' EC');if(d.thrust&&!d.water)values.push('推力 '+((f.engineThrust.get(id)||0)/1000).toFixed(1)+' kN');const heat=f.thermal.get(id);if(heat)values.push('温度 '+heat.temperature.toFixed(0)+' K');w.readings.textContent=values.join('\n');
  }
 }
 function open(id,x,y){const f=getFlight(),p=f?.parts.find(p=>p.id===id);if(!p)return;if(vessel!==f)clear();vessel=f;if(windows.has(id)){windows.get(id).front();return;}for(const [other,w]of windows)if(!w.pinned)close(other);
  const d=PARTS[p.type],w=floatingWindow(host,{title:d.name+' · '+(f.parts.indexOf(p)+1),x:x+12,y:y+12,onClose:()=>close(id)});windows.set(id,w);w.element.onpointerenter=()=>highlight(id);w.element.onpointerleave=()=>highlight(null);
  for(const a of partActions(f,id)){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.dataset.action=a.key;const state=document.createElement('small');label.append(document.createTextNode(a.label),state,input);w.content.append(label);input.onchange=()=>{if(getFlight()!==f)return;beforeAction();setPartAction(f,id,a.key,input.checked);update();};}
  if(d.parachute){const box=document.createElement('div'),status=document.createElement('output'),buttons=new Map();box.className='fuelTransfer';status.setAttribute('aria-label','パラシュート状態');box.append(status);for(const a of parachuteActions(f,id)){const button=document.createElement('button');button.textContent=a.label;buttons.set(a.key,button);button.onclick=()=>{if(getFlight()!==f)return;beforeAction();setParachuteAction(f,id,a.key);update();};box.append(button);}const conditions=document.createElement('small');conditions.textContent='降下中 · 高度5 km未満 · 250 m/s未満で縮帆。1.5 km未満 · 80 m/s未満で全開。大気と安全な動圧が必要。切離し後は再使用不可。';status.title=conditions.textContent;buttons.get('cut').title='切離し後は再使用できません';w.content.append(box);w.chute={status,buttons};}
  if(d.thrust){const label=document.createElement('label');label.className='partThrustLimit';const name=document.createElement('span');name.textContent='推力上限';w.limitValue=document.createElement('span');w.limit=document.createElement('input');w.limit.type='range';w.limit.min=0;w.limit.max=100;w.limit.step=1;w.limit.setAttribute('aria-label','推力上限');w.limit.title='全体スロットル × この部品の推力上限';label.append(name,w.limitValue,w.limit);w.content.append(label);w.limit.oninput=()=>{if(getFlight()!==f)return;beforeAction();setPartThrustLimit(f,id,Number(w.limit.value)/100);update();};}
  if(d.controlAxis){const label=document.createElement('label');label.className='partThrustLimit';const name=document.createElement('span');name.textContent='舵角上限';w.travelValue=document.createElement('span');w.travel=document.createElement('input');w.travel.type='range';w.travel.min=0;w.travel.max=d.maxDeflection||(d.controlAxis==='auto'?18:25);w.travel.step=.5;w.travel.setAttribute('aria-label','舵角上限');label.append(name,w.travelValue,w.travel);w.content.append(label);w.travel.oninput=()=>{if(getFlight()!==f)return;beforeAction();setPartControlLimit(f,id,Number(w.travel.value)/Number(w.travel.max));update();};}
  if(d.fuel||d.monoprop){const box=document.createElement('div');box.className='fuelTransfer';const target=document.createElement('label'),select=document.createElement('select');select.setAttribute('aria-label','移送相手');target.append('移送相手',select);const quantity=document.createElement('label'),amount=document.createElement('input');amount.type='number';amount.min='0.1';amount.max=String(transferCapacity(p));amount.step=d.monoprop?'1':'10';amount.value=d.monoprop?'1':'100';amount.setAttribute('aria-label','移送量 kg');quantity.append('移送量 kg',amount);const actions=document.createElement('div'),send=document.createElement('button'),receive=document.createElement('button'),status=document.createElement('div');status.setAttribute('role','status');send.textContent='送る →';receive.textContent='← 受け取る';actions.append(send,receive);box.append(target,quantity,actions,status);w.content.append(box);w.transfer={select,amount,send,receive,status};select.onchange=update;amount.oninput=update;
   const move=out=>{if(getFlight()!==f)return;beforeAction();const n=f.transferFuel(out?id:select.value,out?select.value:id,Number(amount.value));status.textContent=n>0?n.toFixed(1)+' kg 移送済み':'移送できません';update();};send.onclick=()=>move(true);receive.onclick=()=>move(false);
  }
  w.readings=document.createElement('output');w.content.append(w.readings);update();w.clamp();
 }
 return {open,update,clear};
}
